"""Finding 3b: line numbering vs snapshot; retrieved_at disagreements; download captured_at; D1 recount."""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from vr7_db import con, q
c=con()
q(c,"select count(*) filter (c.receipt_line=r.ln), count(*) filter (c.receipt_line=r.ln-1) from (select * from r where kind='cap' using sample 20000 rows (reservoir, 7)) r join c on c.receipt_key='receipts/'||r.rk and c.sha256=r.sha256","snapshot receipt_line convention (1-based = first)")
q(c,"""select count(*), count(*) filter (try_cast(json_extract_string(times::json,'$.retrieved_at') as timestamptz)::date = try_cast(regexp_extract(rk,'(\\d{4}-\\d\\d-\\d\\d)/',1) as date)) from l where rk like '%/download-%' and times like '%"retrieved_at"%'""","download lines with retrieved_at; same day as write prefix")
q(c,"""select r_mode, r_outcome, (times like '%captured_at%') has_cap, count(*) from l where rk like '%/download-%' and times like '%"retrieved_at"%' and try_cast(json_extract_string(times::json,'$.retrieved_at') as timestamptz)::date <> try_cast(regexp_extract(rk,'(\\d{4}-\\d\\d-\\d\\d)/',1) as date) group by all order by 4 desc limit 10""","download lines whose retrieved_at is not the write date: mode/outcome")
q(c,"""select r_mode, r_outcome, count(*) from l where rk like '%/download-%' and times like '%captured_at%' group by all order by 3 desc""","download lines with captured_at: mode/outcome")
q(c,"select count(*) filter (mx=n), count(*) filter (mx=n-1), count(*) from (select receipt_key, max(receipt_line) mx from c group by 1) s join (select 'receipts/'||rk k, count(*) n from l group by 1) t on s.receipt_key=t.k","receipts where snapshot max(receipt_line)=line count (1-based) vs =count-1 (0-based)")
q(c,"""select json_extract_string(times::json,'$.captured_at')::timestamptz::date d, regexp_extract(rk,'(\\d{4}-\\d\\d-\\d\\d)/',1) p, count(*) from l where rk like '%/download-%' and times like '%captured_at%' group by all order by 3 desc limit 8""","download captured_at date vs write date")
q(c,"""select abs(epoch(json_extract_string(times::json,'$.retrieved_at')::timestamptz) - epoch(try_strptime(h_date, '%a, %d %b %Y %H:%M:%S GMT')::timestamptz)) > 5 as is_off, r_mode, regexp_replace(regexp_replace(rk,'/\\d{4}-\\d\\d-\\d\\d/','/D/'),'/(download|corpus-recovery)-.*$','/\\1') shape, count(*) from l where times like '%"retrieved_at"%' and h_date is not null group by all having is_off order by 4 desc limit 10""","retrieved_at more than 5 s from Date: by mode/shape")
q(c,"""select r_transport, regexp_extract(r_requested_url,'^https?://([^/]+)',1) host, count(*) from l where rk like '%/download-%' and times like '%captured_at%' group by all order by 3 desc limit 8""","download lines with captured_at: transport and requested host")
